#include <map>
#include <string.h>

class charstarwrap
{
public:
  char* str;
  charstarwrap(char* s) { str = s; }
  bool operator<(const charstarwrap& csw) const
  {
    return strcmp(str, csw.str) < 0;
  }
  bool operator==(const charstarwrap& csw) const
  {
    return strcmp(str, csw.str) == 0;
  }
};

typedef pair<const charstarwrap, unsigned int> value_type;
typedef _Rb_tree<charstarwrap, value_type, _Select1st<value_type>,
                 less<charstarwrap>, malloc_alloc> tree_type;

template pair<tree_type::iterator, bool>
tree_type::insert_unique(const value_type&);
